        // mass flow (kg/s) = leak_rate * 1.98 / 60000
        const leak_co2 = (this._leak_rate * 1.98 / 60000) * command;

        this.setField("lastLeakCo2", this._leak_co2, leak_co2, (n) => (this._leak_co2 = n));

